              className="widget__resize"
              aria-label={`Изменить размер виджета «${def.title}». Стрелки меняют ширину и высоту.`}
              onPointerDown={(e) => startGesture(e, def.id, 'resize')}
              onKeyDown={(e) => onKey(e, def.id, 'resize')}
            >
              <ResizeIcon />
            </button>
          </section>
        );
      })}
