          <circle cx="3" cy={cy} r="1.4" />
          <circle cx="9" cy={cy} r="1.4" />
        </g>
      ))}
    </svg>
  );
}

function ResizeIcon() {
  return (
    <svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true">
      <path d="M11 3 L3 11 M11 7 L7 11" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" fill="none" />
    </svg>
  );
}

