import { chromium } from 'playwright';

const URL = 'http://127.0.0.1:5180/';
const out = (name) => `/tmp/pw/${name}.png`;
const results = [];
const check = (label, ok, extra = '') => {
  results.push({ label, ok });
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${extra ? '  — ' + extra : ''}`);
};

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1360, height: 1000 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));

await page.goto(URL, { waitUntil: 'networkidle' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'networkidle' });
await page.waitForSelector('.widget');
await page.waitForTimeout(400);

const rects = () =>
  page.$$eval('.widget', (els) =>
    els.map((el) => {
      const r = el.getBoundingClientRect();
      const grid = el.parentElement.getBoundingClientRect();
      return {
        id: el.getAttribute('aria-label'),
        x: r.left - grid.left, y: r.top - grid.top, w: r.width, h: r.height,
      };
    }),
  );
const overlapPairs = (rs) => {
  const bad = [];
  for (let i = 0; i < rs.length; i++) for (let j = i + 1; j < rs.length; j++) {
    const a = rs[i], b = rs[j];
    if (a.x < b.x + b.w - 1 && b.x < a.x + a.w - 1 && a.y < b.y + b.h - 1 && b.y < a.y + a.h - 1) bad.push(`${a.id}×${b.id}`);
  }
  return bad;
};

let rs = await rects();
check('all 5 widgets render', rs.length === 5, rs.map((r) => r.id).join(', '));
check('no overlaps initially', overlapPairs(rs).length === 0);
await page.screenshot({ path: out('01-initial'), fullPage: true });

// --- Drag: move "Выручка" (stat) down-right, next to the channel chart ---
const before = rs.find((r) => r.id === 'Выручка');
const grip = page.locator('section[aria-label="Выручка"] .widget__handle');
const gb = await grip.boundingBox();
await page.mouse.move(gb.x + gb.width / 2, gb.y + gb.height / 2);
await page.mouse.down();
for (let i = 1; i <= 20; i++) await page.mouse.move(gb.x + gb.width / 2 + i * 12, gb.y + gb.height / 2 + i * 6);
await page.waitForTimeout(250);
await page.screenshot({ path: out('02-mid-drag'), fullPage: true });
await page.mouse.up();
await page.waitForTimeout(400);
rs = await rects();
const after = rs.find((r) => r.id === 'Выручка');
check('drag moves the widget', Math.abs(after.x - before.x) > 20 || Math.abs(after.y - before.y) > 20, `before (${before.x|0},${before.y|0}) after (${after.x|0},${after.y|0})`);
check('no overlaps after drag', overlapPairs(rs).length === 0, overlapPairs(rs).join(' '));
await page.screenshot({ path: out('03-after-drag'), fullPage: true });

// --- Resize: grow "Выручка по каналам" ---
const chBefore = (await rects()).find((r) => r.id === 'Выручка по каналам');
const rh = page.locator('section[aria-label="Выручка по каналам"] .widget__resize');
const rb = await rh.boundingBox();
await page.mouse.move(rb.x + 6, rb.y + 6);
await page.mouse.down();
for (let i = 1; i <= 10; i++) await page.mouse.move(rb.x + 6 + i * 6, rb.y + 6 + i * 4);
await page.mouse.up();
await page.waitForTimeout(400);
rs = await rects();
const chAfter = rs.find((r) => r.id === 'Выручка по каналам');
check('resize grows the widget', chAfter.w > chBefore.w + 10 || chAfter.h > chBefore.h + 10, `w ${chBefore.w|0}→${chAfter.w|0}, h ${chBefore.h|0}→${chAfter.h|0}`);
check('no overlaps after resize', overlapPairs(rs).length === 0, overlapPairs(rs).join(' '));

// --- Hover tooltip on the line chart ---
const plot = page.locator('section[aria-label="Выручка по каналам"] .plot');
const pb = await plot.boundingBox();
await page.mouse.move(pb.x + pb.width * 0.5, pb.y + pb.height * 0.5);
await page.waitForTimeout(200);
const tipText = await page.locator('section[aria-label="Выручка по каналам"] .viz-tooltip').first().innerText().catch(() => '');
check('line chart tooltip shows on hover', tipText.includes('Онлайн') && tipText.includes('Итого'), tipText.replace(/\n/g, ' | '));
await page.screenshot({ path: out('04-line-hover'), fullPage: true });

// --- Per-row tooltip on region bars ---
const row = page.locator('section[aria-label^="Выручка по регионам"] .region-row').first();
await row.hover();
await page.waitForTimeout(200);
const rowTipDisplay = await row.locator('.region-tip').evaluate((el) => getComputedStyle(el).display);
check('region bar tooltip shows on hover', rowTipDisplay === 'block', rowTipDisplay);
await page.screenshot({ path: out('05-region-hover'), fullPage: true });

// --- Table view twin ---
await page.locator('section[aria-label="Выручка по каналам"] button', { hasText: 'Таблица' }).click();
await page.waitForTimeout(200);
check('table view renders for channels', (await page.locator('section[aria-label="Выручка по каналам"] table').count()) === 1);
await page.locator('section[aria-label="Выручка по каналам"] button', { hasText: 'График' }).click();

// --- Legend toggle keeps at least one channel visible ---
const legend = page.locator('section[aria-label="Выручка по каналам"] .legend-item');
await legend.nth(0).click();
await legend.nth(1).click();
await legend.nth(2).click();
const pressed = await legend.evaluateAll((els) => els.map((e) => e.getAttribute('aria-pressed')));
check('legend keeps last channel on', pressed.filter((p) => p === 'true').length === 1, pressed.join(','));
await legend.nth(0).click(); // turn one back on for the screenshot
await legend.nth(1).click();

// --- Keyboard move on "Заказы" ---
await page.waitForTimeout(250);
const ordBefore = (await rects()).find((r) => r.id === 'Заказы');
await page.locator('section[aria-label="Заказы"] .widget__handle').focus();
await page.keyboard.press('ArrowRight');
await page.keyboard.press('ArrowRight');
await page.waitForTimeout(300);
const ordAfter = (await rects()).find((r) => r.id === 'Заказы');
check('keyboard arrows move a widget by cells', ordAfter.x > ordBefore.x + 10, `x ${ordBefore.x|0}→${ordAfter.x|0}`);
check('no overlaps after keyboard move', overlapPairs(await rects()).length === 0);

// --- Persistence across reload ---
const beforeReload = await rects();
await page.reload({ waitUntil: 'networkidle' });
await page.waitForSelector('.widget');
await page.waitForTimeout(400);
const afterReload = await rects();
const same = beforeReload.every((r, i) => Math.abs(r.x - afterReload[i].x) < 2 && Math.abs(r.y - afterReload[i].y) < 2 && Math.abs(r.w - afterReload[i].w) < 2);
check('layout persists across reload', same);

// --- Period switch rescales every widget ---
await page.locator('.filter-row .g-select-control, .filter-row button').first().click();
await page.waitForTimeout(200);
const opt = page.getByText('90 дней', { exact: true }).first();
if (await opt.count()) {
  await opt.click();
  await page.waitForTimeout(400);
  const val = await page.locator('section[aria-label="Выручка"]').innerText();
  check('period switch updates stat values', val.length > 0, val.replace(/\n/g, ' | '));
} else {
  check('period switch options visible', false, 'option "90 дней" not found');
}
await page.screenshot({ path: out('06-period-90'), fullPage: true });

// --- Reset ---
await page.getByRole('button', { name: 'Сбросить раскладку' }).click();
await page.waitForTimeout(400);
const reset = await rects();
const stored = await page.evaluate(() => localStorage.getItem('viz-dashboard:layout:v1'));
check('reset restores default positions', reset.find((r) => r.id === 'Выручка').x < 10 && reset.find((r) => r.id === 'Выручка').y < 10 && stored === null || (reset.find((r) => r.id === 'Выручка').x < 10));
await page.screenshot({ path: out('07-reset'), fullPage: true });

check('no console errors or warnings', errors.length === 0, errors.slice(0, 5).join(' || '));

await browser.close();
const failed = results.filter((r) => !r.ok).length;
console.log(`\n${results.length - failed}/${results.length} passed`);
process.exit(failed ? 1 : 0);

